/* Music app switching flows, extracted from app store reviews.
 *
 * Generated by pipeline/switching/export_flows.py from the LLM-labeled review
 * pipeline (run_music_edges.py). Static, so the Flows view works in Demo mode.
 *
 * Directions: source -> target means users move (or lean) from source to target.
 * Each monthly row is split by the app whose reviews it was seen in (`o`), because
 * weight_per_10k is normalized by that app's review volume.
 */

import raw from './flows.json';

export type FlowKind = 'switch' | 'return' | 'intent' | 'preference';
/** Visual layers: switches and returns are drawn together. */
export type FlowLayer = 'switch' | 'intent' | 'preference';

export interface FlowNode {
	id: string;
	name: string;
	/** true when we have this app's own reviews */
	observed: boolean;
	/** labeled edges touching this app, all months */
	edgeCount: number;
	volume?: Record<string, number>;
	totalVolume?: number;
}

export interface FlowEdgeRow {
	m: string;
	s: string;
	t: string;
	k: FlowKind;
	/** app whose reviews this was observed in */
	o: string;
	n: number;
	w: number;
	w10k: number;
	/** reasons, most common first */
	r: [string, number][];
}

export interface FlowExample {
	q: string;
	stars: number | null;
	m: string;
	r: string[];
	d: string;
	o: string;
	src: string;
}

export interface FlowMonth {
	month: string;
	full: boolean;
	missing: string[];
	low: string[];
	note: string;
}

export interface FlowReason {
	id: string;
	label: string;
	description: string;
	count: number;
}

export interface FlowAnnotation {
	month: string;
	label: string;
	detail: string;
}

interface FlowsDataset {
	meta: {
		generatedAt: string;
		model: string;
		edgeRows: number;
		kinds: FlowKind[];
		observed: string[];
		normalization: string;
	};
	months: FlowMonth[];
	coverage: { start: string; end: string; months: string[]; note: string };
	reasons: FlowReason[];
	nodes: FlowNode[];
	edges: FlowEdgeRow[];
	examples: Record<string, FlowExample[]>;
	annotations: FlowAnnotation[];
}

export const flows = raw as unknown as FlowsDataset;

export const flowNodes = flows.nodes;
export const flowMonths = flows.months;
export const allMonthIds = flows.months.map((m) => m.month);
export const coverageMonths = flows.coverage.months;
export const flowAnnotations = flows.annotations;
export const flowReasons = flows.reasons;

const nodeMap = new Map(flowNodes.map((n) => [n.id, n]));
const monthMap = new Map(flowMonths.map((m) => [m.month, m]));
const reasonMap = new Map(flowReasons.map((r) => [r.id, r]));

export function flowNode(id: string): FlowNode | undefined {
	return nodeMap.get(id);
}

export function flowMonth(id: string): FlowMonth | undefined {
	return monthMap.get(id);
}

export function reasonLabel(id: string): string {
	return reasonMap.get(id)?.label ?? id;
}

export function layerOf(kind: FlowKind): FlowLayer {
	return kind === 'return' ? 'switch' : kind;
}

/* ------------------------- reason colours ------------------------- */

/** The most common concrete reasons get their own colour; the rest share grey. */
const REASON_COLOURS: Record<string, string> = {
	ads: 'var(--pink)',
	free_tier_limits: 'var(--amber)',
	price: 'var(--lime)',
	catalog: 'var(--cyan)',
	bugs_performance: 'var(--red)',
	recommendations: 'var(--violet)',
	offline_downloads: 'var(--green)'
};
export const OTHER_COLOUR = 'var(--muted)';

export const legendReasons = flowReasons
	.filter((r) => r.id in REASON_COLOURS)
	.map((r) => ({ ...r, colour: REASON_COLOURS[r.id] }));

export function reasonColour(id: string | undefined): string {
	return (id && REASON_COLOURS[id]) || OTHER_COLOUR;
}

/* -------------------------- aggregation --------------------------- */

export function volumeOf(appId: string, months: string[]): number {
	const v = nodeMap.get(appId)?.volume;
	if (!v) return 0;
	let sum = 0;
	for (const m of months) sum += v[m] ?? 0;
	return sum;
}

export interface FlowAgg {
	s: string;
	t: string;
	layer: FlowLayer;
	/** weight per 10k reviews of the observing app(s), summed across observing apps */
	value: number;
	count: number;
	weight: number;
	kinds: Partial<Record<FlowKind, number>>;
	reasons: Map<string, number>;
}

export function topReason(reasons: Map<string, number>): string | undefined {
	let best: string | undefined;
	let bestN = 0;
	for (const [id, n] of reasons) {
		// "other" only wins when nothing concrete is stated
		const score = id === 'other' ? n - 0.5 : n;
		if (score > bestN) {
			best = id;
			bestN = score;
		}
	}
	return best;
}

export function sortedReasons(reasons: Map<string, number>): [string, number][] {
	return [...reasons].sort((a, b) => b[1] - a[1]);
}

/**
 * Aggregate edges over a set of months for the visible layers.
 * value = sum over observing apps of (weight / that app's review volume in the period) x 10k.
 * For a single month this equals the exported weight_per_10k.
 */
export function aggregate(months: string[], layers: Set<FlowLayer>): Map<string, FlowAgg> {
	const monthSet = new Set(months);
	const volumes = new Map<string, number>();
	const out = new Map<string, FlowAgg>();
	for (const row of flows.edges) {
		if (!monthSet.has(row.m)) continue;
		const layer = layerOf(row.k);
		if (!layers.has(layer)) continue;
		let vol = volumes.get(row.o);
		if (vol === undefined) {
			vol = volumeOf(row.o, months);
			volumes.set(row.o, vol);
		}
		if (!vol) continue;
		const key = `${row.s}|${row.t}|${layer}`;
		let agg = out.get(key);
		if (!agg) {
			agg = { s: row.s, t: row.t, layer, value: 0, count: 0, weight: 0, kinds: {}, reasons: new Map() };
			out.set(key, agg);
		}
		agg.value += (row.w / vol) * 1e4;
		agg.count += row.n;
		agg.weight += row.w;
		agg.kinds[row.k] = (agg.kinds[row.k] ?? 0) + row.n;
		for (const [id, n] of row.r) agg.reasons.set(id, (agg.reasons.get(id) ?? 0) + n);
	}
	return out;
}

/** Per-month value of one directed pair (all months), summed over the given layers. */
export function pairSeries(s: string, t: string, layers: Set<FlowLayer>): { month: string; value: number; count: number }[] {
	const byMonth = new Map<string, { value: number; count: number }>();
	for (const row of flows.edges) {
		if (row.s !== s || row.t !== t || !layers.has(layerOf(row.k))) continue;
		const cur = byMonth.get(row.m) ?? { value: 0, count: 0 };
		cur.value += row.w10k;
		cur.count += row.n;
		byMonth.set(row.m, cur);
	}
	return allMonthIds.map((month) => ({ month, ...(byMonth.get(month) ?? { value: 0, count: 0 }) }));
}

/** Raw switch + intent counts per month, for the timeline histogram. */
export const monthlyActivity: Record<string, number> = (() => {
	const out: Record<string, number> = {};
	for (const row of flows.edges) {
		if (row.k === 'preference') continue;
		out[row.m] = (out[row.m] ?? 0) + row.n;
	}
	return out;
})();

export function examplesFor(s: string, t: string, kind: FlowKind): FlowExample[] {
	return flows.examples[`${s}|${t}|${kind}`] ?? [];
}

const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function fmtMonth(id: string, short = false): string {
	const [y, m] = id.split('-').map(Number);
	const name = MONTH_NAMES[(m ?? 1) - 1] ?? id;
	return short ? `${name} ’${String(y).slice(2)}` : `${name} ${y}`;
}
